/* From Uiverse.io by Lucaasbre  - Tags: simple, button, checkbox, menu, light&dark */
.__UIV_SCOPE__ .button-menu {
  cursor: pointer;
  position: absolute;
  z-index: 1;
  background-color: #ffdd00;
  border: 2px solid #1e1e1e;
  color: #1e1e1e;
  font-size: 30px;
  font-weight: 700;
  width: 60px;
  height: 60px;
  border-radius: 50%;
  display: flex;
  justify-content: center;
  align-items: center;
  text-align: center;
  -webkit-box-shadow: 0px 3px 10px 0px rgba(16, 16, 16, 0.5);
  -moz-box-shadow: 0px 3px 10px 0px rgba(16, 16, 16, 0.5);
  box-shadow: 0px 3px 10px 0px rgba(16, 16, 16, 0.5);
}

.__UIV_SCOPE__ .checkbox {
  width: 60px;
  height: 60px;
  opacity: 0;
  z-index: 10;
  cursor: pointer;
}

.__UIV_SCOPE__ .option {
  position: absolute;
  background-color: #1e1e1e;
  border: 2px solid #ffdd00;
  color: #ffdd00;
  z-index: -1;
  width: 55px;
  height: 55px;
  border-radius: 50%;
  cursor: pointer;
  font-weight: 700;
  transition: all 0.3s;
  -webkit-box-shadow: 3px 3px 10px 0px rgba(16, 16, 16, 0.5);
  -moz-box-shadow: 3px 3px 10px 0px rgba(16, 16, 16, 0.5);
  box-shadow: 3px 3px 10px 0px rgba(16, 16, 16, 0.5);
}

.__UIV_SCOPE__ .checkbox:hover ~ .button-menu,
.__UIV_SCOPE__ .checkbox:checked ~ .button-menu {
  background-color: #eccd00;
  scale: 0.98;
  box-shadow: none;
}

.__UIV_SCOPE__ .checkbox:not(:checked) ~ .button-menu::before {
  content: "+";
}

.__UIV_SCOPE__ .checkbox:checked ~ .button-menu::after {
  content: "-";
  scale: 0.98;
  box-shadow: none;
}

.__UIV_SCOPE__ .checkbox:not(:checked) ~ .option {
  box-shadow: none;
}

.__UIV_SCOPE__ .option:hover,
.__UIV_SCOPE__ .option:active,
.__UIV_SCOPE__ .option:focus {
  box-shadow: none;
  scale: 0.98;
}

.__UIV_SCOPE__ .checkbox:checked ~ .option-a {
  transition-delay: 0.1s;
  transform: translateY(-70px);
}

.__UIV_SCOPE__ .checkbox:checked ~ .option-b {
  transition-delay: 0.2s;
  transform: translateY(-140px);
}

.__UIV_SCOPE__ .checkbox:checked ~ .option-c {
  transition-delay: 0.3s;
  transform: translateY(-210px);
}
